#pragma once

#include <stdint.h>

#define PDA_ICON_SIZE 16

/** One icon: a row per element, bit 15 leftmost, a set bit lit. */
struct pda_icon {
    const char *name;
    uint16_t rows[16];
};

extern const struct pda_icon pda_icons[];
extern const int pda_icon_count;
